import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { 
  Mail, 
  Lock, 
  Eye, 
  EyeOff, 
  LogIn, 
  Facebook, 
  Github, 
  Twitter,
  Sparkles,
  Shield,
  Smartphone,
  Fingerprint,
  AlertCircle
} from 'lucide-react';

const Login = ({ onLogin }) => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    email: '',
    password: '',
  });
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('email');
  const [hoverEffect, setHoverEffect] = useState(false);
  const [error, setError] = useState('');

  // Informations d'identification correctes
  const CORRECT_EMAIL = "enzo@gmail.com";
  const CORRECT_PASSWORD = "41329758@#Enzo";

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Effacer l'erreur quand l'utilisateur commence à taper
    if (error) setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    // Validation des champs
    if (!formData.email.trim() || !formData.password.trim()) {
      setError('Please fill in all fields');
      setLoading(false);
      return;
    }

    // Animation de chargement
    setTimeout(() => {
      // Vérification des identifiants
      if (formData.email === CORRECT_EMAIL && formData.password === CORRECT_PASSWORD) {
        // Si onLogin prop est fournie, l'utiliser
        if (onLogin) {
          onLogin(formData);
        }

        // Sauvegarder dans localStorage si "Remember Me" est coché
        if (rememberMe) {
          localStorage.setItem('userEmail', formData.email);
          localStorage.setItem('rememberMe', 'true');
        } else {
          localStorage.removeItem('userEmail');
          localStorage.removeItem('rememberMe');
        }

        // Redirection vers le dashboard
        navigate('/dashboard');
      } else {
        setError('Invalid email or password. Use: enzo@gmail.com / 41329758@#Enzo');
        setLoading(false);
      }
    }, 1500);
  };

  const handleSocialLogin = (provider) => {
    console.log(`Login with ${provider}`);
    setError(`Social login with ${provider} is not implemented yet. Please use email login.`);
  };

  const handleBiometricLogin = () => {
    setLoading(true);
    setError('');
    setTimeout(() => {
      setError('Biometric login is not available. Please use email login.');
      setLoading(false);
    }, 1500);
  };

  // Charger l'email sauvegardé au chargement du composant
  React.useEffect(() => {
    const savedEmail = localStorage.getItem('userEmail');
    const savedRememberMe = localStorage.getItem('rememberMe');

    if (savedEmail && savedRememberMe === 'true') {
      setFormData(prev => ({ ...prev, email: savedEmail }));
      setRememberMe(true);
    }
  }, []);

  return (
    <div className="min-h-screen bg-gradient-to-br from-neutral-50 via-white to-primary-50 dark:from-neutral-950 dark:via-neutral-900 dark:to-primary-950 overflow-hidden">
      {/* Background Elements */}
      <div className="absolute inset-0 overflow-hidden">
        <div className="absolute -top-40 -right-40 w-80 h-80 bg-gradient-to-r from-primary-300/20 to-secondary-300/20 rounded-full blur-3xl dark:from-primary-500/10 dark:to-secondary-500/10"></div>
        <div className="absolute bottom-40 -left-40 w-80 h-80 bg-gradient-to-r from-accent-300/20 to-primary-300/20 rounded-full blur-3xl dark:from-accent-500/10 dark:to-primary-500/10"></div>
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-96 h-96 bg-gradient-to-r from-secondary-300/10 to-accent-300/10 rounded-full blur-3xl"></div>
      </div>

      <div className="relative min-h-screen flex items-center justify-center p-4">
        <div className="max-w-6xl w-full grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">

          {/* Left Side - Hero Section */}
          <div className="hidden lg:block">
            <div className="relative">
              {/* Animated Card */}
              <div className="relative bg-gradient-to-br from-white/80 to-white/20 dark:from-neutral-900/80 dark:to-neutral-900/20 backdrop-blur-xl rounded-3xl p-8 shadow-2xl border border-white/20 dark:border-neutral-800/50 overflow-hidden">
                {/* Shine Effect */}
                <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full animate-shine"></div>

                <div className="relative z-10">
                  <div className="flex items-center space-x-3 mb-6">
                    <div className="h-14 w-14 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center shadow-lg">
                      <Sparkles className="h-7 w-7 text-white" />
                    </div>
                    <div>
                      <h1 className="text-3xl font-bold bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
                        Welcome Back
                      </h1>
                      <p className="text-neutral-600 dark:text-neutral-400">Test credentials: enzo@gmail.com / 41329758@#Enzo</p>
                    </div>
                  </div>

                  {/* Features List */}
                  <div className="space-y-6">
                    <div className="flex items-start space-x-4 group">
                      <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-primary-100 to-primary-50 dark:from-primary-900/30 dark:to-primary-800/20 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                        <Shield className="h-6 w-6 text-primary-600 dark:text-primary-400" />
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-neutral-900 dark:text-white">Secure Authentication</h3>
                        <p className="text-neutral-600 dark:text-neutral-400 mt-1">Email: enzo@gmail.com</p>
                      </div>
                    </div>

                    <div className="flex items-start space-x-4 group">
                      <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-accent-100 to-accent-50 dark:from-accent-900/30 dark:to-accent-800/20 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                        <Lock className="h-6 w-6 text-accent-600 dark:text-accent-400" />
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-neutral-900 dark:text-white">Password</h3>
                        <p className="text-neutral-600 dark:text-neutral-400 mt-1">Pass: 41329758@#Enzo</p>
                      </div>
                    </div>

                    <div className="flex items-start space-x-4 group">
                      <div className="h-12 w-12 rounded-xl bg-gradient-to-br from-secondary-100 to-secondary-50 dark:from-secondary-900/30 dark:to-secondary-800/20 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                        <Smartphone className="h-6 w-6 text-secondary-600 dark:text-secondary-400" />
                      </div>
                      <div>
                        <h3 className="text-lg font-semibold text-neutral-900 dark:text-white">Demo Account</h3>
                        <p className="text-neutral-600 dark:text-neutral-400 mt-1">Use the credentials above to login</p>
                      </div>
                    </div>
                  </div>

                  {/* Stats */}
                  <div className="mt-8 pt-8 border-t border-neutral-200/50 dark:border-neutral-800/50">
                    <div className="grid grid-cols-3 gap-4">
                      <div className="text-center">
                        <div className="text-2xl font-bold text-primary-600 dark:text-primary-400">Demo</div>
                        <div className="text-sm text-neutral-600 dark:text-neutral-400">Account</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-accent-600 dark:text-accent-400">Test</div>
                        <div className="text-sm text-neutral-600 dark:text-neutral-400">Login</div>
                      </div>
                      <div className="text-center">
                        <div className="text-2xl font-bold text-secondary-600 dark:text-secondary-400">Ready</div>
                        <div className="text-sm text-neutral-600 dark:text-neutral-400">To Use</div>
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Floating Elements */}
              <div className="absolute -top-4 -right-4 h-24 w-24 bg-gradient-to-r from-primary-400 to-secondary-400 rounded-2xl rotate-12 opacity-20 blur-xl"></div>
              <div className="absolute -bottom-4 -left-4 h-20 w-20 bg-gradient-to-r from-accent-400 to-primary-400 rounded-2xl -rotate-12 opacity-20 blur-xl"></div>
            </div>
          </div>

          {/* Right Side - Login Form */}
          <div className="relative">
            <div className={`relative bg-gradient-to-br from-white/90 to-white/70 dark:from-neutral-900/90 dark:to-neutral-900/70 backdrop-blur-xl rounded-3xl p-8 shadow-2xl border border-white/30 dark:border-neutral-800/50 transition-all duration-500 ${hoverEffect ? 'scale-[1.02]' : ''}`}
                 onMouseEnter={() => setHoverEffect(true)}
                 onMouseLeave={() => setHoverEffect(false)}>

              {/* Glow Effect */}
              <div className="absolute -inset-1 bg-gradient-to-r from-primary-500/20 via-secondary-500/20 to-accent-500/20 rounded-3xl blur-xl opacity-70"></div>

              <div className="relative z-10">
                {/* Header */}
                <div className="text-center mb-8">
                  <div className="inline-flex items-center justify-center h-16 w-16 rounded-2xl bg-gradient-to-r from-primary-500 to-secondary-500 mb-4 shadow-lg">
                    <LogIn className="h-8 w-8 text-white" />
                  </div>
                  <h2 className="text-3xl font-bold text-neutral-900 dark:text-white">
                    Welcome Back
                  </h2>
                  <p className="text-neutral-600 dark:text-neutral-400 mt-2">
                    Sign in with: enzo@gmail.com / 41329758@#Enzo
                  </p>
                </div>

                {/* Login Tabs */}
                <div className="flex space-x-2 mb-6 p-1 bg-neutral-100 dark:bg-neutral-800 rounded-2xl">
                  <button
                    onClick={() => {
                      setActiveTab('email');
                      setError('');
                    }}
                    className={`flex-1 py-3 px-4 rounded-xl text-sm font-medium transition-all duration-300 ${activeTab === 'email' ? 'bg-white dark:bg-neutral-700 shadow-md text-primary-600 dark:text-primary-400' : 'text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                  >
                    <Mail className="h-4 w-4 inline mr-2" />
                    Email
                  </button>
                  <button
                    onClick={() => {
                      setActiveTab('phone');
                      setError('Phone login is not available. Please use email login.');
                    }}
                    className={`flex-1 py-3 px-4 rounded-xl text-sm font-medium transition-all duration-300 ${activeTab === 'phone' ? 'bg-white dark:bg-neutral-700 shadow-md text-primary-600 dark:text-primary-400' : 'text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                  >
                    <Smartphone className="h-4 w-4 inline mr-2" />
                    Phone
                  </button>
                  <button
                    onClick={() => {
                      setActiveTab('biometric');
                      setError('Biometric login is not available. Please use email login.');
                    }}
                    className={`flex-1 py-3 px-4 rounded-xl text-sm font-medium transition-all duration-300 ${activeTab === 'biometric' ? 'bg-white dark:bg-neutral-700 shadow-md text-primary-600 dark:text-primary-400' : 'text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white'}`}
                  >
                    <Fingerprint className="h-4 w-4 inline mr-2" />
                    Biometric
                  </button>
                </div>

                {/* Display Error Message */}
                {error && (
                  <div className="mb-6 p-4 rounded-2xl bg-gradient-to-r from-red-50 to-red-100/50 dark:from-red-900/20 dark:to-red-900/10 border border-red-200 dark:border-red-800/50">
                    <div className="flex items-start">
                      <AlertCircle className="h-5 w-5 text-red-500 dark:text-red-400 mt-0.5 mr-3 flex-shrink-0" />
                      <p className="text-sm text-red-700 dark:text-red-300">{error}</p>
                    </div>
                  </div>
                )}

                {/* Login Form */}
                <form className="space-y-6" onSubmit={handleSubmit}>
                  {activeTab === 'email' && (
                    <>
                      <div className="group">
                        <label htmlFor="email" className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                          Email Address
                        </label>
                        <div className="relative">
                          <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                            <Mail className="h-5 w-5 text-neutral-400 group-focus-within:text-primary-500 transition-colors" />
                          </div>
                          <input
                            id="email"
                            name="email"
                            type="email"
                            autoComplete="email"
                            required
                            value={formData.email}
                            onChange={handleChange}
                            className="pl-12 block w-full px-4 py-4 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:border-primary-500 focus:ring-2 focus:ring-primary-500/20 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-neutral-900 transition-all duration-300"
                            placeholder="enzo@gmail.com"
                          />
                        </div>
                      </div>

                      <div className="group">
                        <label htmlFor="password" className="block text-sm font-medium text-neutral-700 dark:text-neutral-300 mb-2">
                          Password
                        </label>
                        <div className="relative">
                          <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                            <Lock className="h-5 w-5 text-neutral-400 group-focus-within:text-primary-500 transition-colors" />
                          </div>
                          <input
                            id="password"
                            name="password"
                            type={showPassword ? "text" : "password"}
                            autoComplete="current-password"
                            required
                            value={formData.password}
                            onChange={handleChange}
                            className="pl-12 pr-12 block w-full px-4 py-4 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl bg-white/50 dark:bg-neutral-800/50 text-neutral-900 dark:text-white placeholder-neutral-500 focus:border-primary-500 focus:ring-2 focus:ring-primary-500/20 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-neutral-900 transition-all duration-300"
                            placeholder="41329758@#Enzo"
                          />
                          <button
                            type="button"
                            className="absolute inset-y-0 right-0 pr-4 flex items-center"
                            onClick={() => setShowPassword(!showPassword)}
                          >
                            {showPassword ? (
                              <EyeOff className="h-5 w-5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300 transition-colors" />
                            ) : (
                              <Eye className="h-5 w-5 text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300 transition-colors" />
                            )}
                          </button>
                        </div>
                      </div>
                    </>
                  )}

                  {activeTab === 'phone' && (
                    <div className="text-center py-8">
                      <div className="inline-flex items-center justify-center h-24 w-24 rounded-2xl bg-gradient-to-r from-primary-500/20 to-secondary-500/20 mb-6">
                        <Smartphone className="h-12 w-12 text-primary-500" />
                      </div>
                      <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                        Phone login is not implemented. Please use email login.
                      </p>
                    </div>
                  )}

                  {activeTab === 'biometric' && (
                    <div className="text-center py-8">
                      <div className="inline-flex items-center justify-center h-24 w-24 rounded-2xl bg-gradient-to-r from-primary-500/20 to-secondary-500/20 mb-6">
                        <Fingerprint className="h-12 w-12 text-primary-500" />
                      </div>
                      <p className="text-neutral-600 dark:text-neutral-400 mb-6">
                        Biometric login is not implemented. Please use email login.
                      </p>
                    </div>
                  )}

                  {activeTab === 'email' && (
                    <>
                      {/* Remember Me & Forgot Password */}
                      <div className="flex items-center justify-between">
                        <div className="flex items-center">
                          <input
                            id="remember-me"
                            name="remember-me"
                            type="checkbox"
                            checked={rememberMe}
                            onChange={() => setRememberMe(!rememberMe)}
                            className="h-5 w-5 text-primary-600 focus:ring-primary-500 border-neutral-300 rounded transition-colors cursor-pointer"
                          />
                          <label htmlFor="remember-me" className="ml-2 block text-sm text-neutral-700 dark:text-neutral-300 cursor-pointer select-none">
                            Remember me
                          </label>
                        </div>

                        <Link
                          to="/forgot-password"
                          className="text-sm font-medium text-primary-600 hover:text-primary-500 dark:text-primary-400 dark:hover:text-primary-300 transition-colors"
                        >
                          Forgot password?
                        </Link>
                      </div>

                      {/* Submit Button */}
                      <div>
                        <button
                          type="submit"
                          disabled={loading}
                          className="group relative w-full flex justify-center py-4 px-4 border border-transparent rounded-2xl text-white font-medium bg-gradient-to-r from-primary-500 to-secondary-500 hover:from-primary-600 hover:to-secondary-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all duration-300 hover:shadow-xl hover:shadow-primary-500/25 transform hover:-translate-y-0.5"
                        >
                          <span className="absolute left-0 inset-y-0 flex items-center pl-4">
                            {loading ? (
                              <div className="h-5 w-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                            ) : (
                              <LogIn className="h-5 w-5 text-white" />
                            )}
                          </span>
                          {loading ? 'Signing in...' : 'Sign In with Demo Account'}
                        </button>
                      </div>
                    </>
                  )}

                  {/* Divider */}
                  {activeTab === 'email' && (
                    <div className="relative">
                      <div className="absolute inset-0 flex items-center">
                        <div className="w-full border-t border-neutral-300 dark:border-neutral-700"></div>
                      </div>
                      <div className="relative flex justify-center text-sm">
                        <span className="px-4 bg-white dark:bg-neutral-900 text-neutral-500">
                          Or continue with (Demo)
                        </span>
                      </div>
                    </div>
                  )}

                  {/* Social Login */}
                  {activeTab === 'email' && (
                    <div className="grid grid-cols-3 gap-3">
                      <button
                        type="button"
                        onClick={() => handleSocialLogin('google')}
                        className="flex items-center justify-center py-3 px-4 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 font-medium hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 hover:shadow-md transition-all duration-300 disabled:opacity-50"
                        disabled
                      >
                        <svg className="w-5 h-5 mr-2" viewBox="0 0 24 24">
                          <path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                          <path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                          <path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                          <path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                        </svg>
                        Google
                      </button>
                      <button
                        type="button"
                        onClick={() => handleSocialLogin('github')}
                        className="flex items-center justify-center py-3 px-4 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 font-medium hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 hover:shadow-md transition-all duration-300 disabled:opacity-50"
                        disabled
                      >
                        <Github className="w-5 h-5 mr-2" />
                        GitHub
                      </button>
                      <button
                        type="button"
                        onClick={() => handleSocialLogin('twitter')}
                        className="flex items-center justify-center py-3 px-4 border-2 border-neutral-200 dark:border-neutral-700 rounded-2xl bg-white/50 dark:bg-neutral-800/50 text-neutral-700 dark:text-neutral-300 font-medium hover:border-primary-500 hover:text-primary-600 dark:hover:text-primary-400 hover:shadow-md transition-all duration-300 disabled:opacity-50"
                        disabled
                      >
                        <Twitter className="w-5 h-5 mr-2" />
                        Twitter
                      </button>
                    </div>
                  )}

                  {/* Register Link */}
                  <div className="text-center pt-4">
                    <p className="text-sm text-neutral-600 dark:text-neutral-400">
                      Don't have an account?{' '}
                      <Link
                        to="/register"
                        className="font-medium text-primary-600 hover:text-primary-500 dark:text-primary-400 dark:hover:text-primary-300 transition-colors group"
                      >
                        Sign up now
                        <span className="inline-block ml-1 group-hover:translate-x-1 transition-transform">→</span>
                      </Link>
                    </p>
                  </div>
                </form>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Floating Particles */}
      <div className="absolute top-1/4 left-1/4 w-2 h-2 bg-primary-400 rounded-full animate-float"></div>
      <div className="absolute top-1/3 right-1/4 w-3 h-3 bg-secondary-400 rounded-full animate-float animation-delay-1000"></div>
      <div className="absolute bottom-1/4 left-1/3 w-2 h-2 bg-accent-400 rounded-full animate-float animation-delay-2000"></div>
    </div>
  );
};

export default Login;
